testo:
{
 "genere": "prevedi",
 "titolo": "Ripasso: Porte, chiavi e interruttori",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> bool:
	var has_key: bool = false
	var door_locked: bool = true
	if has_key:
		door_locked = false
	return door_locked
",
   "domanda": "Quanto vale `door_locked` alla fine?",
   "spiegazione": "`has_key` è falso, quindi il blocco `if` non viene eseguito. `door_locked` resta al suo valore iniziale: `true`."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var keys: int = 1
	var door_cost: int = 1
	if keys >= door_cost:
		keys -= door_cost
		return keys
	return -1
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "`keys` (1) è maggiore o uguale a `door_cost` (1). Il codice dentro l' `if` sottrae il costo, lasciando `keys` a 0, e restituisce 0."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var bodies_on_plate: int = 0
	bodies_on_plate += 1
	bodies_on_plate += 1
	bodies_on_plate -= 1
	return bodies_on_plate
",
   "domanda": "Quanto vale `bodies_on_plate` alla fine?",
   "spiegazione": "Entrano due corpi (+1 e poi +1, arrivando a 2), poi uno esce (-1). Il totale finale è 1."
  },
  {
   "codice": "extends RefCounted


func run() -> bool:
	var player_in_range: bool = true
	var interact_pressed: bool = false
	var can_open: bool = player_in_range and interact_pressed
	return can_open
",
   "domanda": "Quanto vale `can_open` alla fine?",
   "spiegazione": "`player_in_range` è vero, ma `interact_pressed` è falso. Con l'operatore `and` basta che una sola condizione sia falsa per rendere tutto l'enunciato falso: `can_open` è `false`."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var state: String = "closed"
	var switch_flipped: bool = true
	if switch_flipped:
		state = "open"
	return state
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`switch_flipped` è vero, quindi il blocco `if` viene eseguito e cambia la variabile `state` da "closed" a "open"."
  }
 ]
}
